//! Minimal offline WAV drum preview for rhythms generated by DrumsRNN.
//!
//! This is a deliberately simple synthesized *test renderer*, not the final
//! Y2Synth drum DSP. No samples, audio device, JS, or platform APIs are needed.
//! Output: 44,100 Hz, mono, 16-bit PCM WAV, including a short decay tail.

use crate::generation::{DrumHit, GeneratedPattern};
use std::f32::consts::TAU;
use std::fs::File;
use std::io::{self, BufWriter, ErrorKind, Write};
use std::path::Path;

pub const SAMPLE_RATE: u32 = 44_100;

fn invalid(message: impl Into<String>) -> io::Error {
    io::Error::new(ErrorKind::InvalidInput, message.into())
}

fn voice_duration(pitch: u8) -> f32 {
    match pitch {
        36 => 0.36,                // kick
        38 => 0.26,                // snare
        42 => 0.12,                // closed hat
        46 => 0.43,                // open hat
        45 | 48 | 50 => 0.38,     // toms
        49 => 0.90,                // crash
        51 => 0.78,                // ride
        _ => 0.18,
    }
}

/// Simple deterministic noise source. Separate start-state per drum hit.
fn noise_next(state: &mut u64) -> f32 {
    *state = state.wrapping_add(0x9e3779b97f4a7c15);
    let mut value = *state;
    value = (value ^ (value >> 30)).wrapping_mul(0xbf58476d1ce4e5b9);
    value = (value ^ (value >> 27)).wrapping_mul(0x94d049bb133111eb);
    let sample = (value ^ (value >> 31)) >> 40;
    (sample as f32) * (2.0 / 16_777_216.0) - 1.0
}

fn render_voice(samples: &mut [f32], start: usize, hit: DrumHit) {
    if start >= samples.len() {
        return;
    }
    let sample_rate = SAMPLE_RATE as f32;
    let length = ((voice_duration(hit.pitch) * sample_rate).ceil() as usize)
        .min(samples.len() - start);

    let mut phase = 0.0f32;
    let mut previous_noise = 0.0f32;
    let mut random_state =
        0x8691_31e3_98b4_14a7u64 ^ ((hit.step as u64) << 16) ^ (hit.pitch as u64);

    for index in 0..length {
        let t = index as f32 / sample_rate;
        let noise = noise_next(&mut random_state);
        // Elementary differentiator makes noise brighter (not a high-fidelity filter).
        let bright_noise = noise - 0.82 * previous_noise;
        previous_noise = noise;

        let (frequency, amplitude) = match hit.pitch {
            36 => {
                let frequency = 50.0 + 115.0 * (-t * 30.0).exp();
                (frequency, 0.86 * (-t * 16.0).exp() * phase.sin())
            }
            38 => (
                185.0,
                0.29 * bright_noise * (-t * 20.0).exp()
                    + 0.15 * phase.sin() * (-t * 24.0).exp(),
            ),
            42 => (
                440.0,
                0.24 * bright_noise * (-t * 54.0).exp(),
            ),
            46 => (
                440.0,
                0.24 * bright_noise * (-t * 13.0).exp(),
            ),
            45 | 48 | 50 => {
                let base = match hit.pitch {
                    45 => 120.0,
                    48 => 155.0,
                    _ => 198.0,
                };
                (
                    base * (0.8 + 0.4 * (-t * 19.0).exp()),
                    0.58 * phase.sin() * (-t * 14.0).exp(),
                )
            }
            49 | 51 => {
                let decay = if hit.pitch == 49 { 4.7 } else { 6.0 };
                (
                    603.0,
                    (0.23 * bright_noise + 0.065 * (phase * 1.414).sin())
                        * (-t * decay).exp(),
                )
            }
            _ => (
                440.0,
                0.10 * bright_noise * (-t * 35.0).exp(),
            ),
        };
        // Apply a short attack to prevent a hard discontinuity at the onset.
        let attack = (t / 0.0015).min(1.0);
        samples[start + index] += amplitude * attack;
        phase += TAU * frequency / sample_rate;
        if phase >= TAU {
            phase -= TAU;
        }
    }
}

/// Produce a mono signal from the model's drum hits at the given BPM.
///
/// Each model step is a sixteenth note (four steps per quarter note).
/// The generated pattern is *not* modified, re-quantized, or regenerated.
pub fn render_samples(pattern: &GeneratedPattern, bpm: f32) -> io::Result<Vec<f32>> {
    if !bpm.is_finite() || !(40.0..=240.0).contains(&bpm) {
        return Err(invalid("BPM must be finite and in 40..=240"));
    }
    if pattern.classes.is_empty() {
        return Err(invalid("Cannot render a zero-step pattern"));
    }
    let step_seconds = 60.0f64 / bpm as f64 / 4.0;
    let length_seconds = step_seconds * pattern.classes.len() as f64 + 1.0;
    let length = (length_seconds * SAMPLE_RATE as f64).ceil() as usize;
    // Protect against accidentally attempting multi-gigabyte recordings.
    if length > (u32::MAX as usize / 2).saturating_sub(36) {
        return Err(invalid("Pattern too long for 16-bit RIFF/WAV"));
    }
    let mut samples = vec![0.0f32; length];

    for &hit in &pattern.hits {
        if hit.step >= pattern.classes.len() {
            return Err(invalid("Drum hit outside pattern"));
        }
        let start = (hit.step as f64 * step_seconds * SAMPLE_RATE as f64).round() as usize;
        render_voice(&mut samples, start, hit);
    }

    let peak = samples.iter().fold(0.0f32, |peak, sample| peak.max(sample.abs()));
    // Normalize down or up to 80% of full scale, but preserve all-rest silence.
    if peak > 0.0 {
        let gain = 0.8 / peak;
        for sample in &mut samples {
            *sample *= gain;
        }
    }
    Ok(samples)
}

/// Write RIFF/WAVE PCM16 mono. No external crate or backend is required.
pub fn write_wav(path: &Path, pattern: &GeneratedPattern, bpm: f32) -> io::Result<()> {
    let samples = render_samples(pattern, bpm)?;
    let byte_count = samples.len().checked_mul(2)
        .and_then(|count| u32::try_from(count).ok())
        .ok_or_else(|| invalid("Rendered WAV exceeds 4 GB file limit"))?;
    let riff_size = byte_count.checked_add(36)
        .ok_or_else(|| invalid("Rendered WAV exceeds RIFF header limit"))?;

    let mut writer = BufWriter::new(File::create(path)?);
    writer.write_all(b"RIFF")?;
    writer.write_all(&riff_size.to_le_bytes())?;
    writer.write_all(b"WAVE")?;
    writer.write_all(b"fmt ")?;
    writer.write_all(&16u32.to_le_bytes())?;              // PCM fmt chunk
    writer.write_all(&1u16.to_le_bytes())?;               // PCM integer
    writer.write_all(&1u16.to_le_bytes())?;               // mono
    writer.write_all(&SAMPLE_RATE.to_le_bytes())?;
    writer.write_all(&(SAMPLE_RATE * 2).to_le_bytes())?;    // byte rate
    writer.write_all(&2u16.to_le_bytes())?;               // block alignment
    writer.write_all(&16u16.to_le_bytes())?;              // bits per sample
    writer.write_all(b"data")?;
    writer.write_all(&byte_count.to_le_bytes())?;
    for sample in samples {
        let sample_i16 = (sample.clamp(-1.0, 1.0) * i16::MAX as f32).round() as i16;
        writer.write_all(&sample_i16.to_le_bytes())?;
    }
    writer.flush()
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::fs;

    fn test_pattern(hits: Vec<DrumHit>) -> GeneratedPattern {
        GeneratedPattern {
            classes: vec![0; 16],
            hits,
            diagnostics: vec![],
        }
    }

    #[test]
    fn silence_renders_to_zero_pcm() {
        let audio = render_samples(&test_pattern(vec![]), 120.0).unwrap();
        assert_eq!(audio.len(), 132_300); // two seconds plus one-second tail
        assert!(audio.iter().all(|sample| *sample == 0.0));
    }

    #[test]
    fn synthesized_kick_is_finite_and_audible() {
        let audio = render_samples(
            &test_pattern(vec![DrumHit { step: 0, pitch: 36 }]),
            120.0,
        )
        .unwrap();
        assert!(audio.iter().all(|sample| sample.is_finite()));
        assert!(audio.iter().any(|sample| sample.abs() > 0.1));
        assert!(audio.iter().all(|sample| sample.abs() <= 1.0));
    }

    #[test]
    fn late_hit_does_not_sound_early() {
        let audio = render_samples(
            &test_pattern(vec![DrumHit { step: 8, pitch: 38 }]),
            120.0,
        )
        .unwrap();
        assert!(audio[..SAMPLE_RATE as usize].iter().all(|sample| *sample == 0.0));
        assert!(audio[SAMPLE_RATE as usize..]
            .iter().any(|sample| sample.abs() > 0.05));
    }

    #[test]
    fn invalid_tempo_is_rejected() {
        assert!(render_samples(&test_pattern(vec![]), 0.0).is_err());
        assert!(render_samples(&test_pattern(vec![]), f32::NAN).is_err());
        assert!(render_samples(&test_pattern(vec![]), 500.0).is_err());
    }

    #[test]
    fn wav_has_valid_pcm_header_and_data_length() {
        let path = std::env::temp_dir().join(format!(
            "y2synth-wav-test-{}.wav", std::process::id()
        ));
        write_wav(
            &path,
            &test_pattern(vec![DrumHit { step: 0, pitch: 36 }]),
            120.0,
        )
        .unwrap();
        let bytes = fs::read(&path).unwrap();
        let _ = fs::remove_file(path);
        assert_eq!(&bytes[0..4], b"RIFF");
        assert_eq!(&bytes[8..12], b"WAVE");
        assert_eq!(&bytes[12..16], b"fmt ");
        assert_eq!(u16::from_le_bytes([bytes[20], bytes[21]]), 1); // PCM
        assert_eq!(u16::from_le_bytes([bytes[22], bytes[23]]), 1); // mono
        assert_eq!(&bytes[36..40], b"data");
        let expected_data = u32::from_le_bytes(bytes[40..44].try_into().unwrap());
        assert_eq!(bytes.len(), 44 + expected_data as usize);
        assert_eq!(u32::from_le_bytes(bytes[4..8].try_into().unwrap()) as usize + 8, bytes.len());
    }
}
